+      console.log([row.id, row.name, row.packageId, row.status, row.context, row.format]
+        .map((value) => JSON.stringify(value))
+        .join(","));
+    }
+    return;
+  }
+
+  const authored = rows.filter((row) => row.status === "authored").length;
